function r(t){return String(t).padStart(2,"0")}function e(t){if(!t)return"-";const n=new Date(t);return Number.isNaN(n.getTime())?String(t):`${n.getFullYear()}-${r(n.getMonth()+1)}-${r(n.getDate())} ${r(n.getHours())}:${r(n.getMinutes())}:${r(n.getSeconds())}`}function o(t,n=2){return t==null||t===""?"-":typeof t=="string"?t:t.toFixed(n)}function f(t,n){const i=o(t,2);return i==="-"?"-":n?`${i} ${n}`:i}function s(t){return t==null||t===""?"-":t}function c(t,n=60){return t?t.length>n?`${t.slice(0,n)}…`:t:"-"}function u(t){if(!(t==null||t===""))return String(t)}function g(t){if(t==null)return"";try{return JSON.stringify(t,null,2)}catch{return String(t)}}export{o as a,f as b,c,e as f,g as p,u as s,s as t};
